// data/*.tsv compiled into the library (headers generated by cmake/embed.cmake).
#include <string_view>

#include "tables.h"
#include "zcode_data_keyboard.h"
#include "zcode_data_rules.h"
#include "zcode_data_shapes.h"
#include "zcode_data_zcode.h"

namespace zcode {
namespace {

std::string_view view(const unsigned char* data, std::size_t size) {
    // Each generated array carries one trailing NUL that is not part of the file.
    return std::string_view(reinterpret_cast<const char*>(data), size - 1);
}

}  // namespace

bool Tables::parse_embedded(Tables& out, std::string& error) {
    return parse(out, view(zcode_data_zcode, sizeof zcode_data_zcode),
                 view(zcode_data_shapes, sizeof zcode_data_shapes), view(zcode_data_rules, sizeof zcode_data_rules),
                 view(zcode_data_keyboard, sizeof zcode_data_keyboard), error);
}

}  // namespace zcode
